<?php require_once __DIR__.'/config/configuracion.php';$mensaje='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);$m=new mysqli(BD_HOST,BD_USUARIO,BD_CLAVE);$m->query('CREATE DATABASE IF NOT EXISTS '.BD_NOMBRE.' CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$b=new mysqli(BD_HOST,BD_USUARIO,BD_CLAVE,BD_NOMBRE);$b->set_charset('utf8mb4');$b->multi_query(file_get_contents(__DIR__.'/sql/estructura_sccmgpc.sql'));while($b->more_results()&&$b->next_result()){}for($i=1;$i<=33;$i++){$n='Distrito Local '.sprintf('%02d',$i);$s=$b->prepare('INSERT INTO distritos(numero_distrito,nombre_distrito) VALUES(?,?) ON DUPLICATE KEY UPDATE nombre_distrito=VALUES(nombre_distrito)');$s->bind_param('is',$i,$n);$s->execute();}$cuentas=[['control01','Control General 1','CONTROL_GENERAL',null,'ControlMGPC2028!'],['control02','Control General 2','CONTROL_GENERAL',null,'ControlMGPC2028!']];for($i=1;$i<=33;$i++)$cuentas[]=[sprintf('distrito%02d',$i),'Usuario Distrito Local '.sprintf('%02d',$i),'DISTRITO',$i,sprintf('Distrito%02d!', $i)];foreach($cuentas as [$nom,$completo,$perfil,$num,$clave]){$idD=null;if($num)$idD=$b->query('SELECT id_distrito FROM distritos WHERE numero_distrito='.(int)$num)->fetch_row()[0];$hash=password_hash($clave,PASSWORD_DEFAULT);$s=$b->prepare('INSERT INTO usuarios(nombre_usuario,clave_hash,nombre_completo,perfil,id_distrito) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE clave_hash=VALUES(clave_hash),nombre_completo=VALUES(nombre_completo),perfil=VALUES(perfil),id_distrito=VALUES(id_distrito),activo=1,debe_cambiar_clave=1');$s->bind_param('ssssi',$nom,$hash,$completo,$perfil,$idD);$s->execute();}$totalUsuarios=(int)$b->query("SELECT COUNT(*) FROM usuarios WHERE activo=1")->fetch_row()[0];if($totalUsuarios<35)throw new RuntimeException('No se pudieron crear las 35 cuentas. Total encontrado: '.$totalUsuarios);$mensaje='Instalación terminada. Se conservaron los datos de seccxut y se verificaron '.$totalUsuarios.' usuarios activos.';}catch(Throwable $e){$error=$e->getMessage();}}?><!doctype html><html lang="es"><head><meta charset="utf-8"><link rel="stylesheet" href="public/css/estilos.css"><title>Instalador SCCMGPC</title></head><body><div class="login"><div class="tarjeta"><h1>Instalador SCCMGPC</h1><?php if($mensaje):?><div class="aviso"><?=$mensaje?></div><a class="boton" href="index.php">Ir al inicio de sesión</a><?php elseif($error):?><div class="aviso error"><?=htmlspecialchars($error)?></div><?php else:?><p>El instalador utilizará la base <b>sccmgpc</b>, no modificará <b>seccxut</b> y creará las tablas en español junto con 35 cuentas.</p><form method="post"><button class="boton">Instalar sistema completo</button></form><p><a href="crear_usuarios.php">Si las tablas ya existen, crear o reparar únicamente los 35 usuarios</a></p><?php endif?></div></div></body></html>